        parsed = self.process_args(args)
        super().__init__(tree_file_path=parsed["tree_file_path"])
        self.json_output = parsed["json_output"]

    def run(self) -> None:
        simple_summary = self._get_simple_newick_summary(
            self.tree_file_path,
            "tree_file_path",
